<?php
require __DIR__.'/config/bootstrap.php';
function run_ems(string $page): void {
    $role=current_user()['role']??'';
    $adminHr=['admin','hr'];
    $roles=match($page){'dashboard'=>['admin','hr','employee'],'employees','departments','attendance','leaves','reports'=> $adminHr,'users','activity','settings'=>['admin'],'profile','my-attendance','my-leave','notifications'=>['employee'],default=>[]};
    require_roles($roles);
    $isStaff=in_array($role,$adminHr,true);
    verify_csrf();
    $self=current_employee();
    if($role==='employee'&&!$self){ http_response_code(403); echo 'No employee profile is connected to this account. Ask HR to link your profile.'; return; }
    $errors=[];
    if($_SERVER['REQUEST_METHOD']==='POST'){
        $a=$_POST['action']??'';$pdo=db();
        try {
            if($a==='employee_save'&&$isStaff){
                $id=(int)($_POST['id']??0);$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$dept=(int)($_POST['department_id']??0);$designation=trim($_POST['designation']??'');$joining=$_POST['joining_date']??'';
                if(!$first||!$last||!$email||!$designation||!$joining)throw new RuntimeException('Complete all required employee fields with a valid email.');
                if($id){$pdo->prepare('UPDATE employees SET first_name=?,last_name=?,email=?,phone=?,department_id=?,designation=?,joining_date=?,employment_status=? WHERE id=?')->execute([$first,$last,$email,trim($_POST['phone']??''),$dept?:null,$designation,$joining,$_POST['employment_status']??'active',$id]);$pdo->prepare('UPDATE users u JOIN employees e ON e.user_id=u.id SET u.email=? WHERE e.id=?')->execute([$email,$id]);log_activity('Employee updated',"$first $last");flash('success','Employee details saved.');}
                else{$eid='EMP'.str_pad((string)(int)$pdo->query('SELECT COALESCE(MAX(id),0)+1 FROM employees')->fetchColumn(),3,'0',STR_PAD_LEFT);$username=strtolower(preg_replace('/[^a-z0-9]/i','',substr($email,0,strpos($email,'@')))).random_int(10,99);$pdo->beginTransaction();$pdo->prepare("INSERT INTO users(username,email,password,role) VALUES(?,?,?,'employee')")->execute([$username,$email,password_hash(($tempPass=bin2hex(random_bytes(5))),PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO employees(employee_id,user_id,first_name,last_name,email,phone,department_id,designation,joining_date) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$eid,$uid,$first,$last,$email,trim($_POST['phone']??''),$dept?:null,$designation,$joining]);$pdo->commit();log_activity('Employee created',"$eid · $first $last");flash('success',"Employee added. Share the temporary password $tempPass with the employee.");}
                redirect(($role==='admin'?'admin':'hr').'/employees.php');
            }
            if($a==='employee_status'&&$isStaff){$id=(int)$_POST['id'];$status=$_POST['status']==='inactive'?'inactive':'active';$pdo->prepare('UPDATE employees SET employment_status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('UPDATE users u JOIN employees e ON e.user_id=u.id SET u.status=? WHERE e.id=?')->execute([$status,$id]);log_activity('Employee status changed',"Employee #$id · $status");flash('success','Employee status updated.');redirect(($role==='admin'?'admin':'hr').'/employees.php');}
            if($a==='department_save'&&$isStaff){$id=(int)($_POST['id']??0);$name=trim($_POST['department_name']??'');$code=strtoupper(trim($_POST['department_code']??''));if(!$name||!$code)throw new RuntimeException('Enter a department name and code.');if($id)$pdo->prepare('UPDATE departments SET department_name=?,department_code=?,description=?,status=? WHERE id=?')->execute([$name,$code,trim($_POST['description']??''),$_POST['status']??'active',$id]);else $pdo->prepare('INSERT INTO departments(department_name,department_code,description) VALUES(?,?,?)')->execute([$name,$code,trim($_POST['description']??'')]);log_activity($id?'Department updated':'Department created',$name);flash('success','Department saved.');redirect(($role==='admin'?'admin':'hr').'/departments.php');}
            if($a==='attendance_mark'&&$isStaff){$emp=(int)($_POST['employee_id']??0);$date=$_POST['attendance_date']??date('Y-m-d');$status=$_POST['status']??'Present';$valid=['Present','Absent','Late','Half Day','Leave'];if(!in_array($status,$valid,true))throw new RuntimeException('Choose a valid attendance status.');$pdo->prepare('INSERT INTO attendance(employee_id,attendance_date,check_in,check_out,status,remarks) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE check_in=VALUES(check_in),check_out=VALUES(check_out),status=VALUES(status),remarks=VALUES(remarks)')->execute([$emp,$date,$_POST['check_in']?:null,$_POST['check_out']?:null,$status,trim($_POST['remarks']??'')]);log_activity('Attendance updated',"Employee #$emp · $date · $status");flash('success','Attendance record saved.');redirect(($role==='admin'?'admin':'hr').'/attendance.php');}
            if($a==='check_in'&&$role==='employee'){$pdo->prepare("INSERT INTO attendance(employee_id,attendance_date,check_in,status) VALUES(?,CURDATE(),CURTIME(),'Present') ON DUPLICATE KEY UPDATE check_in=IF(check_in IS NULL,CURTIME(),check_in)")->execute([$self['id']]);log_activity('Attendance check-in','Employee check-in');flash('success','You’re checked in.');redirect('employee/attendance.php');}
            if($a==='check_out'&&$role==='employee'){$pdo->prepare('UPDATE attendance SET check_out=CURTIME() WHERE employee_id=? AND attendance_date=CURDATE() AND check_in IS NOT NULL')->execute([$self['id']]);log_activity('Attendance check-out','Employee check-out');flash('success','You’re checked out.');redirect('employee/attendance.php');}
            if($a==='leave_apply'&&$role==='employee'){$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$reason=trim($_POST['reason']??'');if(!$start||!$end||$end<$start||!$reason)throw new RuntimeException('Enter valid dates and a reason for your request.');$pdo->prepare('INSERT INTO leaves(employee_id,leave_type,start_date,end_date,reason) VALUES(?,?,?,?,?)')->execute([$self['id'],$_POST['leave_type']??'Annual',$start,$end,$reason]);$admins=$pdo->query("SELECT id FROM users WHERE role IN ('admin','hr') AND status='active'")->fetchAll();foreach($admins as $u)notify_user((int)$u['id'],'New leave request',$self['first_name'].' '.$self['last_name'].' submitted a leave request.','info');log_activity('Leave submitted',"{$self['employee_id']} · $start to $end");flash('success','Your leave request has been submitted.');redirect('employee/leaves.php');}
            if($a==='leave_review'&&$isStaff){$id=(int)$_POST['id'];$status=$_POST['status']==='Approved'?'Approved':'Rejected';$pdo->prepare('UPDATE leaves SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status=\'Pending\'')->execute([$status,current_user()['id'],$id]);if($pdo->rowCount()!==1)throw new RuntimeException('This request has already been reviewed.');$q=$pdo->prepare('SELECT e.user_id FROM leaves l JOIN employees e ON e.id=l.employee_id WHERE l.id=?');$q->execute([$id]);$uid=$q->fetchColumn();if($uid)notify_user((int)$uid,'Leave '.$status,'Your leave request was '.$status.'.',strtolower($status)==='approved'?'success':'warning');log_activity('Leave '.$status,"Request #$id");flash('success','Leave request '.$status.'.');redirect(($role==='admin'?'admin':'hr').'/leaves.php');}
            if($a==='profile_save'&&$role==='employee'){$first=trim($_POST['first_name']??'');$last=trim($_POST['last_name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);if(!$first||!$last||!$email)throw new RuntimeException('Enter your name and a valid email.');$pdo->prepare('UPDATE employees SET first_name=?,last_name=?,email=?,phone=?,address=?,city=? WHERE id=?')->execute([$first,$last,$email,trim($_POST['phone']??''),trim($_POST['address']??''),trim($_POST['city']??''),$self['id']]);$pdo->prepare('UPDATE users SET email=? WHERE id=?')->execute([$email,current_user()['id']]);$_SESSION['user']['email']=$email;log_activity('Profile updated','Employee profile');flash('success','Your profile has been updated.');redirect('employee/profile.php');}
            if($a==='user_create'&&$role==='admin'){$email=trim($_POST['email']??'');$validEmail=(bool)filter_var($email,FILTER_VALIDATE_EMAIL)||(bool)preg_match('/^[A-Za-z0-9._%+-]+@[A-Za-z0-9][A-Za-z0-9-]*$/D',$email);$username=trim($_POST['username']??'');$pass=$_POST['password']??'';$r=$_POST['role']??'hr';if(!$validEmail||!$username||strlen($pass)<8||!in_array($r,['admin','hr'],true))throw new RuntimeException('Provide a valid username, email or local account address, role and password (8+ characters).');$pdo->prepare('INSERT INTO users(username,email,password,role) VALUES(?,?,?,?)')->execute([$username,$email,password_hash($pass,PASSWORD_DEFAULT),$r]);log_activity('User created',"$username · $r");flash('success','User account created.');redirect('admin/users.php');}
            if($a==='notification_read'&&$role==='employee'){$pdo->prepare('UPDATE notifications SET is_read=1 WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],current_user()['id']]);flash('success','Notification marked as read.');redirect('employee/notifications.php');}
        } catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof RuntimeException?$ex->getMessage():'Could not save this change. Check required fields and make sure unique values are not already in use.';}
    }
    $title=match($page){'dashboard'=>'Overview','employees'=>'People','departments'=>'Departments','attendance'=>'Attendance','leaves'=>'Leave management','reports'=>'Reports','users'=>'User access','activity'=>'Activity log','settings'=>'Workspace settings','profile'=>'My profile','my-attendance'=>'My attendance','my-leave'=>'My leave','notifications'=>'Notifications',default=>'EMS'};
    if(isset($_GET['export'])&&$isStaff&&$page==='reports') export_report($_GET['export']);
    $q=trim($_GET['q']??'');$deptFilter=(int)($_GET['department']??0);$statusFilter=trim($_GET['status']??'');$dateFrom=$_GET['from']??date('Y-m-01');$dateTo=$_GET['to']??date('Y-m-d');
    $pdo=db();$employeeQuery='SELECT e.*,d.department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id';$employees=$pdo->query($employeeQuery.' ORDER BY e.id DESC')->fetchAll();$departments=$pdo->query('SELECT d.*, (SELECT COUNT(*) FROM employees e WHERE e.department_id=d.id) employee_count FROM departments d ORDER BY d.department_name')->fetchAll();
    $today=date('Y-m-d');$attToday=(int)$pdo->query("SELECT COUNT(*) FROM attendance WHERE attendance_date=CURDATE() AND status IN ('Present','Late')")->fetchColumn();$totalActive=(int)$pdo->query("SELECT COUNT(*) FROM employees WHERE employment_status='active'")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM leaves WHERE status='Pending'")->fetchColumn();$todayAbsent=(int)$pdo->query("SELECT COUNT(*) FROM attendance WHERE attendance_date=CURDATE() AND status='Absent'")->fetchColumn();$unread=0;if($role==='employee'){$st=$pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0');$st->execute([current_user()['id']]);$unread=(int)$st->fetchColumn();}
    $flashes=take_flashes();$base=app_url();$nav=$role==='admin'?['dashboard'=>'Overview','employees'=>'People','departments'=>'Departments','attendance'=>'Attendance','leaves'=>'Leave management','reports'=>'Reports','users'=>'User access','activity'=>'Activity log','settings'=>'Settings']:($role==='hr'?['dashboard'=>'Overview','employees'=>'People','departments'=>'Departments','attendance'=>'Attendance','leaves'=>'Leave management','reports'=>'Reports']:['dashboard'=>'Overview','profile'=>'My profile','my-attendance'=>'My attendance','my-leave'=>'My leave','notifications'=>'Notifications']);
    $prefix=$role==='admin'?'admin':($role==='hr'?'hr':'employee');$urls=['dashboard'=>'dashboard.php','employees'=>'employees.php','departments'=>'departments.php','attendance'=>'attendance.php','leaves'=>'leaves.php','reports'=>'reports.php','users'=>'users.php','activity'=>'activity.php','settings'=>'settings.php','profile'=>'profile.php','my-attendance'=>'attendance.php','my-leave'=>'leaves.php','notifications'=>'notifications.php'];
    ?><!doctype html><html lang="en" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · EMS</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@500;600;700&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?=e($base.'/assets/css/style.css')?>"></head><body><div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="<?=e($base.'/index.php')?>"><span class="brand-mark">E</span><span>EMS<span class="brand-sub">PEOPLE SYSTEMS</span></span></a><div class="workspace-switch"><span class="workspace-dot"></span><span><b><?=e(setting('company_name','EMS Workspace'))?></b><small>People workspace</small></span><span class="chevron">⌄</span></div><div class="nav-caption">WORKSPACE</div><nav class="side-nav"><?php foreach($nav as $key=>$label):?><a class="nav-link <?=$page===$key?'active':''?>" href="<?=e($base.'/'.$prefix.'/'.$urls[$key])?>"><span class="nav-icon"><?=['dashboard'=>'◫','employees'=>'♙','departments'=>'▦','attendance'=>'◷','leaves'=>'▤','reports'=>'⌁','users'=>'♧','activity'=>'◌','settings'=>'⚙','profile'=>'◉','my-attendance'=>'◷','my-leave'=>'▤','notifications'=>'♧'][$key]?></span><span><?=e($label)?></span><?php if($key==='notifications'&&$unread):?><span class="nav-count"><?=$unread?></span><?php endif;?></a><?php endforeach;?></nav><div class="sidebar-bottom"><div class="profile-mini"><span class="avatar"><?=e(strtoupper(substr(current_user()['username'],0,1)))?></span><span class="user-mini-text"><b><?=e(current_user()['username'])?></b><small><?=e(ucfirst($role))?></small></span><a class="mini-logout" href="<?=e($base.'/logout.php')?>" title="Sign out">↗</a></div></div></aside><div class="main-column"><header class="topbar"><button class="icon-button mobile-menu" id="menuToggle" aria-label="Open menu">☰</button><div class="crumb">Workspace <span>/</span> <b><?=e($title)?></b></div><div class="top-actions"><span class="today-label"><?=e(date('D, M j'))?></span><?php if($role==='employee'):?><a class="icon-button notif-button" href="<?=e($base.'/employee/notifications.php')?>" aria-label="Notifications">♧<?php if($unread):?><i></i><?php endif;?></a><?php endif;?><button class="theme-toggle icon-button" type="button" aria-label="Toggle theme">◐</button><span class="top-divider"></span><span class="avatar small-avatar"><?=e(strtoupper(substr(current_user()['username'],0,1)))?></span><span class="top-user"><?=e(current_user()['username'])?><small><?=e(ucfirst($role))?></small></span><a class="signout-link" href="<?=e($base.'/logout.php')?>">Sign out</a></div></header><main class="content">
    <?php foreach($flashes as [$t,$m]):?><div class="toast <?=$t?>" data-toast><?=e($m)?><button type="button" class="toast-close" aria-label="Dismiss">×</button></div><?php endforeach;?><?php foreach($errors as $m):?><div class="toast danger"><?=e($m)?></div><?php endforeach;?>
    <div class="page-heading"><div><span class="eyebrow"><?=e(strtoupper($role))?> WORKSPACE</span><h1><?=e($title)?></h1><p class="muted-text"><?=e(match($page){'dashboard'=>'Here’s what’s happening across your people today.','employees'=>'Your people, roles and employee records.','departments'=>'Organize teams and see how they’re growing.','attendance'=>'A clear view of time, presence and check-ins.','leaves'=>'Review requests and keep time away in sync.','reports'=>'Useful snapshots, built from your workspace data.','profile'=>'Keep your personal details up to date.','my-attendance'=>'Your check-ins and attendance history.','my-leave'=>'Requests, decisions and time away.','notifications'=>'Updates related to your account.','users'=>'Manage who can access this workspace.','activity'=>'A record of important workspace changes.','settings'=>'Basic settings for your workspace.',default=>'A clear view of your people operations.'})?></p></div><?php if($page==='employees'&&$isStaff):?><button class="button primary" data-modal-open="employee-modal">＋ Add employee</button><?php elseif($page==='departments'&&$isStaff):?><button class="button primary" data-modal-open="department-modal">＋ Add department</button><?php elseif($page==='my-leave'&&$role==='employee'):?><button class="button primary" data-modal-open="leave-modal">＋ Request leave</button><?php elseif($page==='users'&&$role==='admin'):?><button class="button primary" data-modal-open="user-modal">＋ Add user</button><?php endif;?></div>
    <?php render_module($page,$role,$pdo,$employees,$departments,$self,$q,$deptFilter,$statusFilter,$dateFrom,$dateTo,$today,$attToday,$totalActive,$pending,$todayAbsent,$base); ?>
    </main><footer class="footer">© <?=date('Y')?> <?=e(setting('company_name','EMS Workspace'))?> <span>·</span> Built for better work.</footer></div></div><div class="sidebar-scrim" id="sidebarScrim"></div>
    <?php render_modals($page,$role,$employees,$departments,$base); ?><script src="<?=e($base.'/assets/js/app.js')?>"></script></body></html><?php
}

function export_report(string $type): never {
    $pdo=db();$rows=[];$filename='ems-report.csv';
    if($type==='employees'){$rows=$pdo->query('SELECT e.employee_id,e.first_name,e.last_name,e.email,e.phone,d.department_name,e.designation,e.joining_date,e.employment_status FROM employees e LEFT JOIN departments d ON d.id=e.department_id ORDER BY e.employee_id')->fetchAll();$filename='employee-report.csv';}
    elseif($type==='attendance'){$q=$pdo->prepare('SELECT e.employee_id,CONCAT(e.first_name,\' \' ,e.last_name) employee,e.department_id,a.attendance_date,a.check_in,a.check_out,a.status,a.remarks FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE a.attendance_date BETWEEN ? AND ? ORDER BY a.attendance_date DESC');$q->execute([$_GET['from']??date('Y-m-01'),$_GET['to']??date('Y-m-d')]);$rows=$q->fetchAll();$filename='attendance-report.csv';}
    elseif($type==='leaves'){$rows=$pdo->query('SELECT e.employee_id,CONCAT(e.first_name,\' \' ,e.last_name) employee,l.leave_type,l.start_date,l.end_date,l.status,l.reason FROM leaves l JOIN employees e ON e.id=l.employee_id ORDER BY l.created_at DESC')->fetchAll();$filename='leave-report.csv';}
    header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as $r)fputcsv($out,$r);}fclose($out);exit;
}

function render_module(string $page,string $role,PDO $pdo,array $employees,array $departments,?array $self,string $q,int $deptFilter,string $statusFilter,string $dateFrom,string $dateTo,string $today,int $attToday,int $totalActive,int $pending,int $todayAbsent,string $base): void {
    $staff=in_array($role,['admin','hr'],true);$eid=(int)($self['id']??0);$link=fn($p)=>e($base.'/'.$role.'/'.$p.'.php');
    if($page==='dashboard'){
        if($staff){$rate=$totalActive?round(($attToday/$totalActive)*100):0;$recent=$pdo->query('SELECT a.*,e.first_name,e.last_name,e.employee_id,d.department_name FROM attendance a JOIN employees e ON e.id=a.employee_id LEFT JOIN departments d ON d.id=e.department_id WHERE a.attendance_date=CURDATE() ORDER BY a.check_in DESC LIMIT 5')->fetchAll();$activities=$role==='admin'?$pdo->query('SELECT l.*,u.username FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 5')->fetchAll():[];?><section class="kpi-grid"><article class="kpi-card"><span class="kpi-icon purple">♙</span><span class="kpi-label">Active employees</span><strong><?=$totalActive?></strong><small>Across <?=count($departments)?> departments</small><span class="kpi-spark">↗</span></article><article class="kpi-card"><span class="kpi-icon green">◷</span><span class="kpi-label">Present today</span><strong><?=$attToday?></strong><small><?=$rate?>% of active team</small><span class="kpi-spark">↗</span></article><article class="kpi-card"><span class="kpi-icon amber">▤</span><span class="kpi-label">Pending leave</span><strong><?=$pending?></strong><small>Requests awaiting review</small><span class="kpi-spark">→</span></article><article class="kpi-card"><span class="kpi-icon rose">◌</span><span class="kpi-label">Absent today</span><strong><?=$todayAbsent?></strong><small>Recorded for today</small><span class="kpi-spark">→</span></article></section><div class="dashboard-grid"><section class="panel span-two"><div class="panel-head"><div><h2>Today’s attendance</h2><p><?=e(date('l, F j'))?> · Recent check-ins</p></div><a class="text-link" href="<?=$link('attendance')?>">View attendance <span>→</span></a></div><?php if(!$recent):empty_state('◷','No attendance recorded yet','Today’s check-ins will appear here once they’re recorded.');else:?><div class="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>DEPARTMENT</th><th>CHECK IN</th><th>STATUS</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><div class="person-cell"><span class="avatar tint-<?=$r['id']%4?>"><?=e(strtoupper(substr($r['first_name'],0,1).substr($r['last_name'],0,1)))?></span><span><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['employee_id'])?></small></span></div></td><td><?=e($r['department_name']??'—')?></td><td><?=e($r['check_in']?:'—')?></td><td><?=status_badge($r['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="panel"><div class="panel-head"><div><h2>Team snapshot</h2><p>Current headcount by department</p></div><span class="panel-dots">•••</span></div><?php if(!$departments):empty_state('▦','No departments yet','Create a department to start organizing your team.');else:?><div class="department-list"><?php $max=max(1,max(array_column($departments,'employee_count')));foreach(array_slice($departments,0,5) as $d):?><div class="dept-row"><span class="dept-dot"></span><span class="dept-name"><?=e($d['department_name'])?></span><b><?=$d['employee_count']?></b><div class="mini-bar"><i style="width:<?=round($d['employee_count']/$max*100)?>%"></i></div></div><?php endforeach;?></div><?php endif;?></section><?php if($role==='admin'):?><section class="panel span-two"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest changes across your workspace</p></div><a class="text-link" href="<?=$link('activity')?>">All activity →</a></div><?php if(!$activities):empty_state('◌','Quiet for now','Important workspace activity will show up here.');else:?><div class="activity-list"><?php foreach($activities as $a):?><div class="activity-row"><span class="activity-dot"></span><span><b><?=e($a['username']??'System')?></b> <?=e(strtolower($a['action']))?> <small><?=e($a['details'])?></small></span><time><?=e(date('M j · H:i',strtotime($a['created_at'])))?></time></div><?php endforeach;?></div><?php endif;?></section><?php endif;?></div><?php
