function status_badge(string $s): string { return '<span class="badge '.e(badge_class($s)).'"><i></i>'.e($s).'</span>'; }
function empty_state(string $icon,string $title,string $desc): void { ?><div class="empty-state"><span class="empty-icon"><?=e($icon)?></span><h3><?=e($title)?></h3><p><?=e($desc)?></p></div><?php }
function table_leaves(array $list,bool $staff): void { ?><div class="table-wrap"><table><thead><tr><?php if($staff):?><th>EMPLOYEE</th><th>DEPARTMENT</th><?php endif;?><th>TYPE</th><th>DATES</th><th>REASON</th><th>STATUS</th><?php if($staff):?><th>REVIEW</th><?php endif;?></tr></thead><tbody><?php foreach($list as $r):?><tr><?php if($staff):?><td><b><?=e(($r['first_name']??'').' '.($r['last_name']??''))?></b><small class="table-sub"><?=e($r['employee_id']??'')?></small></td><td><?=e($r['department_name']??'—')?></td><?php endif;?><td><?=e($r['leave_type'])?></td><td><?=e(date('M j',strtotime($r['start_date'])))?> – <?=e(date('M j, Y',strtotime($r['end_date'])))?></td><td class="reason-cell"><?=e($r['reason'])?></td><td><?=status_badge($r['status'])?></td><?php if($staff):?><td><?php if($r['status']==='Pending'):?><form method="post" class="review-actions"><?=csrf_field()?><input type="hidden" name="action" value="leave_review"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="text-action approve" name="status" value="Approved">Approve</button><button class="text-action reject" name="status" value="Rejected">Decline</button></form><?php else:?><small><?=e($r['reviewer']??'Reviewed')?></small><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php }
function table_attendance(array $list,bool $staff): void { ?><div class="table-wrap"><table><thead><tr><?php if($staff):?><th>EMPLOYEE</th><?php endif;?><th>DATE</th><th>CHECK IN</th><th>CHECK OUT</th><th>STATUS</th><?php if($staff):?><th>DEPARTMENT</th><?php endif;?></tr></thead><tbody><?php foreach($list as $r):?><tr><?php if($staff):?><td><div class="person-cell"><span class="avatar tint-<?=($r['id']??1)%4?>"><?=e(strtoupper(substr($r['first_name'],0,1).substr($r['last_name'],0,1)))?></span><span><b><?=e($r['first_name'].' '.$r['last_name'])?></b><small><?=e($r['employee_id'])?></small></span></div><?php endif;?><td><?=e(date('M j, Y',strtotime($r['attendance_date'])))?></td><td><?=e($r['check_in']?:'—')?></td><td><?=e($r['check_out']?:'—')?></td><td><?=status_badge($r['status'])?></td><?php if($staff):?><td><?=e($r['department_name']??'—')?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><?php }
function render_modals(string $page,string $role,array $employees,array $departments,string $base): void { $staff=in_array($role,['admin','hr'],true); if($page==='employees'&&$staff):?><div class="modal-backdrop" id="employee-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">PEOPLE DIRECTORY</span><h2 id="employee-modal-title">Add employee</h2></div><button class="icon-button" data-modal-close>×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="employee_save"><input type="hidden" name="id" value=""><label>First name *<input name="first_name" required></label><label>Last name *<input name="last_name" required></label><label>Email *<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Department<select name="department_id"><option value="">Select department</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['department_name'])?></option><?php endforeach;?></select></label><label>Designation *<input name="designation" required></label><label>Joining date *<input type="date" name="joining_date" required value="<?=date('Y-m-d')?>"></label><label>Status<select name="employment_status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Add employee</button></div></form></section></div><?php endif;
if($page==='departments'&&$staff):?><div class="modal-backdrop" id="department-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">TEAM STRUCTURE</span><h2 id="department-modal-title">Add department</h2></div><button class="icon-button" data-modal-close>×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="department_save"><input type="hidden" name="id" value=""><label>Department name *<input name="department_name" required></label><label>Department code *<input name="department_code" required maxlength="20"></label><label class="wide">Description<textarea name="description" rows="3"></textarea></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Save department</button></div></form></section></div><?php endif;
if($page==='attendance'&&$staff):?><div class="modal-backdrop" id="attendance-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">DAILY RECORD</span><h2>Record attendance</h2></div><button class="icon-button" data-modal-close>×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="attendance_mark"><label class="wide">Employee<select name="employee_id" required><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=e($e['employee_id'].' · '.$e['first_name'].' '.$e['last_name'])?></option><?php endforeach;?></select></label><label>Date<input type="date" name="attendance_date" required value="<?=date('Y-m-d')?>"></label><label>Status<select name="status"><?php foreach(['Present','Absent','Late','Half Day','Leave'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Check in<input type="time" name="check_in"></label><label>Check out<input type="time" name="check_out"></label><label class="wide">Remarks<textarea name="remarks" rows="2"></textarea></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Save record</button></div></form></section></div><?php endif;
if($page==='my-leave'&&$role==='employee'):?><div class="modal-backdrop" id="leave-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">TIME AWAY</span><h2>Request leave</h2></div><button class="icon-button" data-modal-close>×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="leave_apply"><label>Leave type<select name="leave_type"><?php foreach(['Annual','Sick','Personal','Unpaid','Other'] as $s):?><option><?=$s?></option><?php endforeach;?></select></label><label>Start date<input type="date" name="start_date" required min="<?=date('Y-m-d')?>"></label><label>End date<input type="date" name="end_date" required min="<?=date('Y-m-d')?>"></label><label class="wide">Reason<textarea name="reason" rows="4" required placeholder="Share a short note for your manager"></textarea></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Submit request</button></div></form></section></div><?php endif;
if($page==='users'&&$role==='admin'):?><div class="modal-backdrop" id="user-modal"><section class="modal-card"><div class="modal-head"><div><span class="eyebrow">WORKSPACE ACCESS</span><h2>Add account</h2></div><button class="icon-button" data-modal-close>×</button></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="user_create"><label>Username<input name="username" required></label><label>Email or local account address<input type="text" name="email" inputmode="email" pattern="[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+([.][A-Za-z0-9-]+)*" required></label><label>Role<select name="role"><option value="hr">HR</option><option value="admin">Admin</option></select></label><label>Password<input type="password" name="password" minlength="8" required></label><div class="form-actions"><button class="button secondary" type="button" data-modal-close>Cancel</button><button class="button primary">Create account</button></div></form></section></div><?php endif;
}
